if (len(in_str) < 1) and (len(in_str) > 18):
    print("Error_1")

for ch in in_str:
    if (ch == '4') or (ch == '7'):
        cntr +=1

if (cntr == 4) or (cntr == 7):
    print("YES")
else:
    print("NO")

n = input()

if n.count('4') + n.count('7') in [4,7]:
    print("YES")
else:
    print('NO')

def lucky_number(n):
    n_str = str(n)
    c = 0
    for digit in n_str:
        if digit == "4" or digit == "7":
            c += 1
    if c == 4 or c == 7:
        return "YES"
    else:
        return "NO"
n = int(input())
res = lucky_number(n)
print(res)

